SELECT pdg.*
FROM product_demand_group pdg

    pdg.biz_domain_id = #{bizDomainId}
    AND pdg.is_deleted = false

        and pdg.create_date >= #{groupCreateDateStart} and pdg.create_date <= #{groupCreateDateEnd}


        and pdg.owner_id in

            #{item}


    and (pdg.status is null

        or pdg.status in

            #{item}

    )

        AND EXISTS (
            SELECT 1
            FROM product_demand_group_item pdgi
            JOIN product_demand pd ON pdgi.product_demand_id = pd.id
            JOIN product_line pl ON pd.product_line_id = pl.id

                pdg.id = pdgi.product_demand_group_id
                AND pdgi.product_demand_id = pd.id
                and pd.id = #{id}
                and pd.name like concat('%',#{name},'%')

                    and pd.create_date >= #{createDateStart} and pd.create_date <= #{createDateEnd}


                    and pd.modify_date >= #{modifyDateStart} and pd.modify_date <= #{modifyDateEnd}


                    and pd.expect_schedule_time >= #{expectScheduleTimeStart} and pd.expect_schedule_time <= #{expectScheduleTimeEnd}


                    and pd.priority in

                        #{item}



                    and pd.product_line_id in

                        #{item}



                    and pl.biz_domain_id =  #{bizDomainId}


                    and pd.status in

                        #{item}



                    and pd.id not in

                        #{item}



                    and pd.id  in

                        #{item}



                    and pd.id not in

                        #{item}



                    and pd.type REGEXP CONCAT('[', #{types},']')

                and  pd.is_deleted =false


        )

mapper.update:
UPDATE product_demand_group
SET position = #{position},
    version = version + 1,
    modify_man = #{modifyMan},
    modify_man_id = #{modifyManId}
WHERE id = #{id} and is_deleted = false and version = #{version}

UPDATE product_demand_group
SET is_deleted = true, modify_man_id = #{modifyManId}, modify_man = #{modifyMan}
WHERE id = #{id} and is_deleted = false
